import{_ as r,o,c as s,a2 as t}from"./chunks/framework.Zh78JZbW.js";const m=JSON.parse('{"title":"Compte et appareils","description":"","frontmatter":{},"headers":[],"relativePath":"guide/compte.md","filePath":"guide/compte.md"}'),a={name:"guide/compte.md"};function u(i,e,n,p,l,d){return o(),s("div",null,[...e[0]||(e[0]=[t('<h1 id="compte-et-appareils" tabindex="-1">Compte et appareils <a class="header-anchor" href="#compte-et-appareils" aria-label="Permalink to &quot;Compte et appareils&quot;">​</a></h1><p>Votre pseudo vous est réservé dès que vous le choisissez. Un <strong>mot de passe</strong> permet de le retrouver sur un autre ordinateur ; Kodus ne vous le demande pas à chaque lancement.</p><h2 id="proteger-son-pseudo" tabindex="-1">Protéger son pseudo <a class="header-anchor" href="#proteger-son-pseudo" aria-label="Permalink to &quot;Protéger son pseudo&quot;">​</a></h2><p>Juste après le choix du pseudo, Kodus propose de définir un mot de passe. Vous pouvez aussi le faire plus tard : <strong>Paramètres</strong> → onglet <strong>Profil</strong> → <strong>Compte</strong> → <strong>Définir un mot de passe</strong>.</p><ul><li>8 caractères minimum ;</li><li>les mots de passe trop courants (« azerty123 », « minecraft »…) et ceux qui contiennent votre pseudo sont refusés.</li></ul><p>Sans mot de passe, votre pseudo reste réservé à votre ordinateur, mais vous ne pourrez pas le récupérer sur un autre PC.</p><div class="tip custom-block"><p class="custom-block-title">Comment votre mot de passe est protégé</p><p>Le mot de passe ne quitte jamais votre ordinateur en clair : Kodus en calcule une empreinte, que le serveur protège à nouveau avant de la stocker. Aucune adresse email n&#39;est demandée.</p></div><h2 id="utiliser-kodus-sur-un-autre-ordinateur" tabindex="-1">Utiliser Kodus sur un autre ordinateur <a class="header-anchor" href="#utiliser-kodus-sur-un-autre-ordinateur" aria-label="Permalink to &quot;Utiliser Kodus sur un autre ordinateur&quot;">​</a></h2><ol><li>Installez Kodus sur le nouvel ordinateur.</li><li>Saisissez votre pseudo habituel au premier lancement.</li><li>Kodus indique que ce pseudo est protégé : entrez votre mot de passe, puis cliquez sur <strong>Relier ce PC</strong>.</li></ol><p>Le nouvel ordinateur apparaît ensuite dans la liste de vos appareils. Après plusieurs mots de passe erronés, les tentatives sont bloquées pendant quelques minutes.</p><h2 id="mes-appareils" tabindex="-1">Mes appareils <a class="header-anchor" href="#mes-appareils" aria-label="Permalink to &quot;Mes appareils&quot;">​</a></h2><p><strong>Paramètres</strong> → onglet <strong>Profil</strong> → <strong>Compte</strong> → <strong>Mes appareils</strong> liste les ordinateurs reliés à votre pseudo (« PC Windows », « Mac », « PC Linux »), avec leur date d&#39;ajout et de dernière activité.</p><p>Le bouton <strong>Déconnecter</strong> retire un appareil, par exemple un ordinateur prêté ou perdu. Sans votre mot de passe, il ne pourra plus lancer le jeu avec votre pseudo, ni modifier votre compte ou votre skin.</p><p>Sur un ordinateur déconnecté, le bouton <strong>Jouer</strong> demande le mot de passe pour relier à nouveau le PC, ou propose de choisir un autre pseudo. Sans connexion internet, Kodus ne peut pas vérifier : le jeu se lance normalement, pour pouvoir jouer en solo.</p><h2 id="mot-de-passe-oublie" tabindex="-1">Mot de passe oublié <a class="header-anchor" href="#mot-de-passe-oublie" aria-label="Permalink to &quot;Mot de passe oublié&quot;">​</a></h2><p>Contactez l&#39;équipe Kodus : elle peut réinitialiser votre mot de passe. À la prochaine ouverture de Kodus sur l&#39;un de vos appareils reliés, un nouveau mot de passe vous sera demandé.</p><p>Si vous n&#39;avez plus accès à aucun appareil relié, l&#39;équipe peut libérer votre pseudo : vous pourrez alors le réserver à nouveau.</p><h2 id="mise-a-jour-obligatoire" tabindex="-1">Mise à jour obligatoire <a class="header-anchor" href="#mise-a-jour-obligatoire" aria-label="Permalink to &quot;Mise à jour obligatoire&quot;">​</a></h2><p>Pour protéger les comptes, le serveur Kodus refuse les versions trop anciennes. Si Kodus affiche <strong>Mise à jour obligatoire</strong>, cliquez sur <strong>Mettre à jour</strong> (ou téléchargez la dernière version depuis la page <a href="/kodus-releases/telecharger">Télécharger</a>).</p>',19)])])}const g=r(a,[["render",u]]);export{m as __pageData,g as default};
